content.content:
"use client";

import Link from "next/link";
import { useEffect, useState, useSyncExternalStore } from "react";

import { hiddenTextNotice } from "@/lib/hidden-text";
import { parsePendingRun, pendingRunSnapshot } from "@/lib/pending-run";
import { readReportFlags, type ReportFlags } from "@/lib/report-flags";
import { showLoginWallHelp } from "@/lib/report-logic";
import { formatSeconds, runSeconds, siteName, verdictKindOf } from "@/lib/report-view";
import type { Run, RunDetails, RunLink, Step } from "@/lib/types";

import { CheckAgain, RetestBanner, RetestView } from "./check-again";
import { Findings, Frictions } from "./findings";
import { LiveRun } from "./live-run";
import { displayUrl, formatCost } from "./report-bits";
import { HowMade } from "./how-made";
import { FirstImpressionPanel, HiddenTextLine, ShortAnswer, VerdictHero, heroTitle } from "./report-v2";
import { SharePanel } from "./share-panel";
import { StepsStrip } from "./steps-strip";

const POLL_MS = 2000;

// The remembered address and goal never change while the page is open, so nothing needs to subscribe.
const noSubscription = () => () => {};

type State = { kind: "loading" } | { kind: "not_found" } | { kind: "ready"; data: RunDetails };

export function RunView({ id }: { id: string }) {
  const [state, setState] = useState<State>({ kind: "loading" });
  const [connectionTrouble, setConnectionTrouble] = useState(false);
  // Which Report v2 sections show. `?report=basic` on the address hides them all for that view.
  // Nothing rendered before the run loads depends on it, so reading the address here is safe.
  const pendingRaw = useSyncExternalStore(
    noSubscription,
    () => pendingRunSnapshot(id),
    () => null,
  );
  const [flags] = useState<ReportFlags>(() => readReportFlags(typeof window === "undefined" ? "" : window.location.search));

  useEffect(() => {
    let cancelled = false;
    let timer: ReturnType<typeof setTimeout> | undefined;

    async function poll() {
      try {
        const response = await fetch(`/api/runs/${encodeURIComponent(id)}`, { cache: "no-store" });
        if (cancelled) return;
        if (response.status === 404) {
          setState({ kind: "not_found" });
          return;
        }
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const data = (await response.json()) as RunDetails;
        if (cancelled) return;
        setState({ kind: "ready", data });
        setConnectionTrouble(false);
        if (data.run.status === "done" || data.run.status === "failed") return;
      } catch {
        if (cancelled) return;
        setConnectionTrouble(true);
      }
      timer = setTimeout(poll, POLL_MS);
    }

    poll();
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [id]);

  // Until the first response, the waiting view shows at once, with the address and goal the form remembered.
  if (state.kind === "loading") {
    return (
      <main className="fu-page" style={{ gap: "var(--block-gap)" }}>
        {connectionTrouble && <ConnectionNotice />}
        <LiveRun run={null} steps={[]} pending={parsePendingRun(pendingRaw)} />
      </main>
    );
  }
  if (state.kind === "not_found") return <NotFound />;

  const { run, steps, frictions, original, latest_retest: latestRetest } = state.data;
  const running = run.status === "queued" || run.status === "running";
  return (
    <main className="fu-page" style={{ gap: "var(--block-gap)" }}>
      <ReportHeader run={run} steps={steps} flags={flags} running={running} />
      {(connectionTrouble || (flags.checkAgain && (run.retest_of || latestRetest))) && (
        <div className="-mt-6 flex flex-col gap-3">
          {flags.checkAgain && <RetestBanner run={run} latest={latestRetest} />}
          {connectionTrouble && <ConnectionNotice />}
        </div>
      )}
      {running ? (
        <InProgress run={run} steps={steps} flags={flags} original={original} />
      ) : (
        <Report run={run} steps={steps} frictions={frictions} flags={flags} original={original} />
      )}
    </main>
  );
}

function ReportHeader({ run, steps, flags, running }: { run: Run; steps: Step[]; flags: ReportFlags; running: boolean }) {
  const site = siteName(run.url);
  const facts = flags.facts ? run.run_facts : null;
  const meta = running
    ? []
    : [
        `${facts?.steps_taken ?? steps.length} steps`,
        formatSeconds(runSeconds(run)),
        formatCost(facts?.cost_usd ?? run.cost_usd),
        ...(facts?.agent_version ? [`Agent ${facts.agent_version}`] : []),
      ].filter((item) => item !== "—");
  const sections: [string, string][] = running
    ? []
    : [
        ["Verdict", "fu-r-verdict"],
        ...(flags.answers ? ([["Short answer", "fu-r-short"]] as [string, string][]) : []),
        ...(run.findings !== null ? ([["Findings", "fu-r-find"]] as [string, string][]) : []),
        ["Every step", "fu-r-steps"],
        ["How it was made", "fu-r-made"],
      ];
  return (
    <div className="flex flex-col gap-[18px]">
      <div className="flex flex-wrap items-center justify-between gap-3.5">
        <div className="flex min-w-0 items-center gap-3">
          <span aria-hidden className="flex size-11 flex-none items-center justify-center rounded-field border-[1.5px] border-ink bg-page-btn text-[18px] font-bold text-white">
            {site.charAt(0).toUpperCase()}
          </span>
          <div className="flex min-w-0 flex-col gap-[3px]">
            <a href={run.url} target="_blank" rel="noopener noreferrer nofollow" className="truncate text-[17px] font-semibold">
              {displayUrl(run.url)}
            </a>
            <span className="text-[14px] text-ink3 [overflow-wrap:anywhere]">Goal · {run.goal}</span>
            {run.start_url && (
              <span className="text-[13px] text-ink3 [overflow-wrap:anywhere]">
                Start link ·{" "}
                <a href={run.start_url} target="_blank" rel="noopener noreferrer nofollow" className="fu-link">
                  {displayUrl(run.start_url)}
                </a>
              </span>
            )}
          </div>
        </div>
        {meta.length > 0 && (
          <ul className="m-0 flex list-none flex-wrap gap-1.5 p-0" aria-label="About this run">
            {meta.map((item) => (
              <li key={item} className="flex h-[30px] items-center whitespace-nowrap rounded-pill border border-line bg-s1 px-[11px] font-code text-[12px] font-medium text-ink2">
                {item}
              </li>
            ))}
          </ul>
        )}
      </div>
      {sections.length > 0 && (
        <nav aria-label="Report sections" className="flex gap-1.5 overflow-x-auto pb-0.5 [scrollbar-width:none]">
          {sections.map(([label, anchor], index) => (
            <a
              key={anchor}
              href={`#${anchor}`}
              className="flex h-9 flex-none items-center gap-2 whitespace-nowrap rounded-pill border-[1.5px] border-ink bg-bg px-3.5 text-[14px] font-medium transition-[background,transform] duration-200 hover:-translate-y-0.5 hover:bg-acc-soft hover:text-ink"
            >
              <span className="font-code text-[11px] font-medium text-ink3">0{index + 1}</span>
              {label}
            </a>
          ))}
        </nav>
      )}
    </div>
  );
}

function InProgress({ run, steps, flags, original }: { run: Run; steps: Step[]; flags: ReportFlags; original?: RunLink | null }) {
  return (
    <>
      {flags.checkAgain && run.retest_of && <RetestView run={run} original={original} />}
      <LiveRun run={run} steps={steps} />
      <FirstImpressionBlock run={run} flags={flags} open />
      {steps.length > 0 && <StepsStrip steps={steps} highlight={new Set()} live />}
    </>
  );
}

function Report({ run, steps, frictions, flags, original }: {
  run: Run;
  steps: Step[];
  frictions: RunDetails["frictions"];
  flags: ReportFlags;
  original?: RunLink | null;
}) {
  const loginHelp = showLoginWallHelp(run, steps);
  const kind = verdictKindOf(run, loginHelp, flags.verdict);
  const title = heroTitle(run, steps, kind, flags);
  const done = run.status === "done";
  // Steps a finding or the verdict points at get a red edge in the strip.
  const highlight = new Set<number>();
  for (const finding of run.findings ?? []) {
    highlight.add(finding.evidence.step);
    for (const seen of finding.also_seen_at ?? []) highlight.add(seen.step);
  }
  if (kind === "stuck" && run.verdict?.where_step != null) highlight.add(run.verdict.where_step);

  return (
    <>
      {flags.checkAgain && run.retest_of && <RetestView run={run} original={original} />}
      <VerdictHero run={run} steps={steps} kind={kind} flags={flags} loginHelp={loginHelp && kind !== "login_wall"} />
      {flags.answers && done && <ShortAnswer run={run} kind={kind} title={title} showBasis={flags.labels} />}
      <FirstImpressionBlock run={run} flags={flags} open={!flags.answers} />
      {done && <Findings run={run} flags={flags} kind={kind} />}
      {frictions.length > 0 && <Frictions frictions={frictions} findings={run.findings} />}
      {flags.checkAgain && done && <CheckAgain run={run} />}
      <StepsStrip steps={steps} highlight={highlight} />
      <HowMade run={run} steps={steps} showFacts={flags.facts} />
      {done && <SharePanel url={run.url} kind={kind} />}
    </>
  );
}

// The first impression, with the hidden-text notice as its own line just above it.
function FirstImpressionBlock({ run, flags, open }: { run: Run; flags: ReportFlags; open: boolean }) {
  const notice = hiddenTextNotice(run.hidden_text, run.first_impression);
  if (!notice && !run.first_impression) return null;
  return (
    <div className="flex flex-col gap-3">
      <HiddenTextLine run={run} />
      {run.first_impression && <FirstImpressionPanel review={run.first_impression} flags={flags} open={open} />}
    </div>
  );
}

function ConnectionNotice() {
  return (
    <p role="status" className="fu-notice m-0">
      Having trouble reaching the server. Still trying…
    </p>
  );
}

function NotFound() {
  return (
    <main className="fu-page gap-5">
      <span className="fu-eyebrow">Report</span>
      <h1 className="fu-display text-pagetitle">We couldn&apos;t find that run</h1>
      <p className="m-0 max-w-[40em] text-[17px] leading-normal text-ink2">
        The link may be mistyped or incomplete. Check it, or start a new run.
      </p>
      <Link href="/#fu-form" className="fu-btn fu-btn-md self-start">
        Start a new run →
      </Link>
    </main>
  );
}
// Shapes returned by GET /api/runs/[id]. Shared by the API route and the run page.

import type { HiddenText } from "./hidden-text.ts";

export type RunStatus = "queued" | "running" | "done" | "failed";
export type Outcome =
  | "achieved"
  | "achieved_unconfirmed"
  | "not_achieved"
  | "unverified"
  | "gave_up"
  | "blocked"
  | "max_steps"
  | "error";

export type Clarity = "yes" | "partly" | "no";

// How the founder chose to let the visitor in (the form's "How should the visitor get in?").
export type AccessMode = "public" | "link" | "account" | "signup";

// What a newcomer sees on the landing page without logging in (written by the worker).
export type FirstImpression = {
  what_it_does: { clear: Clarity; summary: string };
  who_its_for: { clear: Clarity; summary: string };
  main_action: { obvious: Clarity; summary: string };
  hesitations: string[];
  suggestions: string[];
};

// What happened after the visitor submitted a login or sign-up form (worker/login_diagnosis.py).
export type LoginDiagnosis = {
  stage: "sign_in" | "sign_up";
  result: "signed_in" | "rejected" | "needs_verification" | "no_effect";
  challenge: "email_verification" | "captcha" | "two_factor" | null;
  page_message: string | null;
  http_statuses: string[];
  step: number | null;
  url: string | null;
  detail?: string;
};

// Which way in the visit used. Never holds a credential: the test login's values are not stored here.
export type Entry = {
  start_link: string | null;
  access_mode?: AccessMode;
  // A login written on the page itself (a demo login for visitors), typed with the page's own values.
  page_login?: "not_used" | "shown_on_page" | "typed";
  // That login was accepted: the password field went away and the visit moved on. Absent on older runs.
  page_login_worked?: boolean;
  diagnosis?: LoginDiagnosis | null;
  // The site showed a bot check ("Verify you are human"); the visit did not try to get past it.
  bot_check?: { phrase: string; url: string; title: string; step: number } | null;
  test_login: "not_provided" | "provided_not_used" | "used" | "failed";
  self_signup: "not_used" | "used" | "blocked_verification" | "blocked_third_party" | "failed";
  third_party_options: string[];
  created_account_email: string | null;
  blocked_at_login: boolean;
};

// One ranked problem from the report writer (worker/report_writer.py). Every one points at a real step.
export type Finding = {
  title: string;
  severity: "high" | "medium" | "low";
  kind: "site_problem" | "unclear_wording" | "hidden_error";
  expected: string;
  happened: string;
  evidence: {
    step: number;
    url: string | null;
    screenshot_url: string | null;
    page_errors: string[];
    quote: string | null;
  };
  reproduce: string[];
  fix_prompt: string;
  // Steps of the problems the visitor noted that this finding covers, so they are not listed twice.
  covers_steps?: number[];
  // The problem is observed in the run; the fix is our recommendation. Absent on older findings.
  basis?: "observed";
  fix_basis?: "recommendation";
  // Three to five checks a person can make by looking at the page after the change.
  acceptance_criteria?: string[];
  // The same symptom seen again, merged into this finding: the earliest step is `evidence`, these are the rest.
  also_seen_at?: { step: number; url: string | null; screenshot_url: string | null; page_errors: string[] }[];
};

// What a statement in the report rests on: the run record, the independent check, or our suggestion.
export type Basis = "observed" | "verified" | "recommendation";

export type VerdictKind = "got_through" | "unconfirmed" | "stuck" | "login_wall" | "bot_check" | "our_failure";

// One verdict per run (worker/verdict.py).
export type Verdict = {
  kind: VerdictKind;
  headline: string;
  where_step: number | null;
  where_url: string | null;
  evidence_quote: string;
  basis: "observed" | "verified";
  detail?: string;
  ways_in?: string[];
};

// How the report was made (worker/run_facts.py): counted from the run, not written by a model.
export type RunFacts = {
  steps_taken: number;
  recoveries: { step: number; rung: string; how: string; instruction: string }[];
  own_issues: { step: number | null; instruction: string; reason: string | null }[];
  page_reloads: number;
  page_errors: string[];
  page_error_count: number;
  verifier: { verdict: string | null; quote: string } | null;
  success_condition: string | null;
  checked_without_success_condition: boolean;
  cost_usd: number;
  duration_seconds: number;
  agent_version?: string;
  worker_id?: string;
  trace_id?: string | null;
};

// Check again (worker/retest.py): what happened to each finding of the original run.
export type RetestLabel = "fixed" | "still_present" | "not_reached" | "inconclusive" | "new";

export type RetestItem = {
  finding_index?: number;
  title: string;
  kind?: string;
  severity?: string;
  original_step?: number | null;
  original_url?: string | null;
  label: RetestLabel;
  // Which pass produced the label: the independent visit, or the guided follow-up along the original route.
  pass?: "independent" | "guided" | null;
  // A step of this (the retest's) report.
  evidence_step: number | null;
  reason?: string;
  basis?: "observed";
};

export type RetestVerdictSide = {
  kind: VerdictKind;
  headline: string;
  where_step: number | null;
  where_url: string | null;
} | null;

export type RetestResult = {
  original_run_id?: string;
  labels: RetestItem[];
  new: RetestItem[];
  counts?: Record<string, number>;
  verdict?: { before: RetestVerdictSide; after: RetestVerdictSide; change: string; summary: string };
  fixed_means?: string;
  guided?: { attempted: number; followed: number };
  error?: string;
};

export type Run = {
  id: string;
  url: string;
  start_url: string | null;
  has_test_login: boolean;
  access_mode: AccessMode | null;
  first_impression: FirstImpression | null;
  // Evidence that the page hid instructions aimed at AI agents (worker/hidden_text.py): where and how, never the
  // text. Read from the run's result only for this field. See lib/hidden-text.ts for what the page shows of it.
  hidden_text?: HiddenText;
  entry: Entry | null;
  findings: Finding[] | null;
  verdict: Verdict | null;
  run_facts: RunFacts | null;
  success_condition: string | null;
  retest_of: string | null;
  retest: RetestResult | null;
  goal: string;
  status: RunStatus;
  outcome: Outcome | null;
  reason: string | null;
  cost_usd: number | string | null;
  brain_model: string | null;
  created_at: string;
  started_at: string | null;
  finished_at: string | null;
};

export type Step = {
  idx: number;
  tool: string;
  thought: string | null;
  input: Record<string, unknown> | null;
  result: Record<string, unknown> | null;
  url: string | null;
  screenshot_path: string | null;
  created_at: string;
};

export type Friction = {
  id: number;
  step_idx: number | null;
  kind: "site" | "agent_issue";
  severity: "low" | "medium" | "high" | null;
  expected: string | null;
  happened: string | null;
};

// The original of a retest, and the latest check of a run (either may be absent).
export type RunLink = { id: string; status?: string; verdict?: Verdict | null; outcome?: Outcome | null };

export type RunDetails = {
  run: Run;
  steps: Step[];
  frictions: Friction[];
  original?: RunLink | null;
  latest_retest?: RunLink | null;
};

export type ApiError = { error: string; message: string };

// Never includes the test login: it lives in run_secrets, which the web app never reads. Of the run's raw
// result, only the hidden-text evidence is read.
// One string literal, so supabase-js can infer the row type from it.
export const RUN_COLUMNS =
  "id, url, start_url, has_test_login, access_mode, first_impression, hidden_text:result->hidden_text, entry, findings, verdict, run_facts, success_condition, retest_of, retest, goal, status, outcome, reason, cost_usd, brain_model, created_at, started_at, finished_at";
// The same without the columns added on 2026-10-11 (access_mode, findings), for a database whose schema
// has not been updated yet: the run page still loads, without them.
export const RUN_COLUMNS_BEFORE_FINDINGS = RUN_COLUMNS.replace(" access_mode,", "")
  .replace(" findings,", "")
  .replace(" verdict,", "")
  .replace(" run_facts,", "")
  .replace(" success_condition,", "")
  .replace(" retest_of,", "")
  .replace(" retest,", "");
export const STEP_COLUMNS = "idx, tool, thought, input, result, url, screenshot_path, created_at";
export const FRICTION_COLUMNS = "id, step_idx, kind, severity, expected, happened";
// Shapes of a product brief (worker/understand.py writes it; /api/briefs/[id] returns it).

export type ClaimStatus = "confirmed" | "inferred" | "unknown";
export type PricingStatus = "published" | "not_published" | "unclear";

export type BriefClaim = {
  claim: string;
  source_url: string;
  status: ClaimStatus;
  // A short exact quote from the source page; empty unless the claim is confirmed.
  quote: string;
};

export type PricingTier = { name: string; price: string; what_you_get: string; source_url: string };

export type SuggestedJourney = {
  goal: string;
  // How we would know it worked.
  success: string;
  source_url: string;
  basis: "call_to_action" | "claim";
  basis_text: string;
  // A site's claim is a goal to test, never proof that it works.
  claim_to_test: boolean;
};

// Written by the worker's code, not by a model: shown when a page held text hidden from people and addressed to
// automated agents. The brief records where it was found, never the text.
export const HIDDEN_TEXT_NOTICE =
  "This page contains hidden text addressed to automated agents. It is not visible to people and was ignored.";

export type HiddenTextNote = {
  notice: string;
  found: { url: string; where: string; method: string; blocks: number }[];
};

export type Brief = {
  version: number;
  url: string;
  one_liner: string;
  what_it_does: string;
  who_its_for: string;
  how_it_works: string;
  primary_value: string;
  pricing: { status: PricingStatus; tiers: PricingTier[]; note: string; source_urls: string[] };
  business_model: { label: "inferred"; model: string; evidence: { quote: string; source_url: string }[] };
  claims: BriefClaim[];
  unknowns: string[];
  suggested_journeys: SuggestedJourney[];
  pages: { url: string; kind: string; title: string; method: "http" | "browser"; status: number; bytes: number }[];
  skipped: { url: string; kind: string; reason: string }[];
  limits: { seconds: number; browser_reads: number; stopped: string | null };
  hidden_text?: HiddenTextNote | null;
};

// A site that could not be read: the run is "failed" and the brief says why, in words for the visitor.
export type BriefFailure = { status: "could_not_read"; message: string };

export type BriefRun = {
  id: string;
  url: string;
  status: "queued" | "running" | "done" | "failed";
  brief: Brief | BriefFailure | null;
  cost_usd: number | string | null;
  created_at: string;
  started_at: string | null;
  finished_at: string | null;
};

// One string literal, so supabase-js can infer the row type from it.
export const BRIEF_COLUMNS = "id, url, status, brief, cost_usd, created_at, started_at, finished_at";
import "server-only";

import { supabase } from "@/lib/supabase";

// A test run started from a brief records which brief it came from (runs.brief_run_id). Both steps are
// best-effort: a database that has not had the "Understand mode" SQL yet still starts the test.

export async function briefExists(briefId: string): Promise<boolean> {
  const { data, error } = await supabase()
    .from("runs")
    .select("id")
    .eq("id", briefId)
    .eq("kind", "understand")
    .maybeSingle();
  if (error) {
    console.error("Looking up the brief failed:", error.message);
    return false;
  }
  return !!data;
}

export async function recordBrief(runId: string, briefId: string): Promise<void> {
  const { error } = await supabase().from("runs").update({ brief_run_id: briefId }).eq("id", runId);
  if (error) console.error("Recording the brief on the run failed:", error.message);
}
// What a run was started with (address and goal), remembered in this browser tab for the moment between
// starting it and its first response, so the waiting page can show them at once. Presentation only: nothing is
// sent anywhere, and storage that is missing or throws just means the page waits for the server.

export type PendingRun = { url: string; goal: string };

function key(id: string): string {
  return `fu-run:${id}`;
}

export function rememberPendingRun(id: string, run: PendingRun): void {
  try {
    sessionStorage.setItem(key(id), JSON.stringify({ url: run.url, goal: run.goal }));
  } catch {
    // The waiting page shows the address once the server answers.
  }
}

// The raw stored string (a stable snapshot for useSyncExternalStore), or null.
export function pendingRunSnapshot(id: string): string | null {
  try {
    return sessionStorage.getItem(key(id));
  } catch {
    return null;
  }
}

export function parsePendingRun(raw: string | null): PendingRun | null {
  if (!raw) return null;
  try {
    const value = JSON.parse(raw) as Partial<PendingRun>;
    return typeof value.url === "string" && typeof value.goal === "string" ? { url: value.url, goal: value.goal } : null;
  } catch {
    return null;
  }
}

toolUseResult.stdout:
"use client";

import Link from "next/link";
import { useEffect, useState, useSyncExternalStore } from "react";

import { hiddenTextNotice } from "@/lib/hidden-text";
import { parsePendingRun, pendingRunSnapshot } from "@/lib/pending-run";
import { readReportFlags, type ReportFlags } from "@/lib/report-flags";
import { showLoginWallHelp } from "@/lib/report-logic";
import { formatSeconds, runSeconds, siteName, verdictKindOf } from "@/lib/report-view";
import type { Run, RunDetails, RunLink, Step } from "@/lib/types";

import { CheckAgain, RetestBanner, RetestView } from "./check-again";
import { Findings, Frictions } from "./findings";
import { LiveRun } from "./live-run";
import { displayUrl, formatCost } from "./report-bits";
import { HowMade } from "./how-made";
import { FirstImpressionPanel, HiddenTextLine, ShortAnswer, VerdictHero, heroTitle } from "./report-v2";
import { SharePanel } from "./share-panel";
import { StepsStrip } from "./steps-strip";

const POLL_MS = 2000;

// The remembered address and goal never change while the page is open, so nothing needs to subscribe.
const noSubscription = () => () => {};

type State = { kind: "loading" } | { kind: "not_found" } | { kind: "ready"; data: RunDetails };

export function RunView({ id }: { id: string }) {
  const [state, setState] = useState<State>({ kind: "loading" });
  const [connectionTrouble, setConnectionTrouble] = useState(false);
  // Which Report v2 sections show. `?report=basic` on the address hides them all for that view.
  // Nothing rendered before the run loads depends on it, so reading the address here is safe.
  const pendingRaw = useSyncExternalStore(
    noSubscription,
    () => pendingRunSnapshot(id),
    () => null,
  );
  const [flags] = useState<ReportFlags>(() => readReportFlags(typeof window === "undefined" ? "" : window.location.search));

  useEffect(() => {
    let cancelled = false;
    let timer: ReturnType<typeof setTimeout> | undefined;

    async function poll() {
      try {
        const response = await fetch(`/api/runs/${encodeURIComponent(id)}`, { cache: "no-store" });
        if (cancelled) return;
        if (response.status === 404) {
          setState({ kind: "not_found" });
          return;
        }
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const data = (await response.json()) as RunDetails;
        if (cancelled) return;
        setState({ kind: "ready", data });
        setConnectionTrouble(false);
        if (data.run.status === "done" || data.run.status === "failed") return;
      } catch {
        if (cancelled) return;
        setConnectionTrouble(true);
      }
      timer = setTimeout(poll, POLL_MS);
    }

    poll();
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [id]);

  // Until the first response, the waiting view shows at once, with the address and goal the form remembered.
  if (state.kind === "loading") {
    return (
      <main className="fu-page" style={{ gap: "var(--block-gap)" }}>
        {connectionTrouble && <ConnectionNotice />}
        <LiveRun run={null} steps={[]} pending={parsePendingRun(pendingRaw)} />
      </main>
    );
  }
  if (state.kind === "not_found") return <NotFound />;

  const { run, steps, frictions, original, latest_retest: latestRetest } = state.data;
  const running = run.status === "queued" || run.status === "running";
  return (
    <main className="fu-page" style={{ gap: "var(--block-gap)" }}>
      <ReportHeader run={run} steps={steps} flags={flags} running={running} />
      {(connectionTrouble || (flags.checkAgain && (run.retest_of || latestRetest))) && (
        <div className="-mt-6 flex flex-col gap-3">
          {flags.checkAgain && <RetestBanner run={run} latest={latestRetest} />}
          {connectionTrouble && <ConnectionNotice />}
        </div>
      )}
      {running ? (
        <InProgress run={run} steps={steps} flags={flags} original={original} />
      ) : (
        <Report run={run} steps={steps} frictions={frictions} flags={flags} original={original} />
      )}
    </main>
  );
}

function ReportHeader({ run, steps, flags, running }: { run: Run; steps: Step[]; flags: ReportFlags; running: boolean }) {
  const site = siteName(run.url);
  const facts = flags.facts ? run.run_facts : null;
  const meta = running
    ? []
    : [
        `${facts?.steps_taken ?? steps.length} steps`,
        formatSeconds(runSeconds(run)),
        formatCost(facts?.cost_usd ?? run.cost_usd),
        ...(facts?.agent_version ? [`Agent ${facts.agent_version}`] : []),
      ].filter((item) => item !== "—");
  const sections: [string, string][] = running
    ? []
    : [
        ["Verdict", "fu-r-verdict"],
        ...(flags.answers ? ([["Short answer", "fu-r-short"]] as [string, string][]) : []),
        ...(run.findings !== null ? ([["Findings", "fu-r-find"]] as [string, string][]) : []),
        ["Every step", "fu-r-steps"],
        ["How it was made", "fu-r-made"],
      ];
  return (
    <div className="flex flex-col gap-[18px]">
      <div className="flex flex-wrap items-center justify-between gap-3.5">
        <div className="flex min-w-0 items-center gap-3">
          <span aria-hidden className="flex size-11 flex-none items-center justify-center rounded-field border-[1.5px] border-ink bg-page-btn text-[18px] font-bold text-white">
            {site.charAt(0).toUpperCase()}
          </span>
          <div className="flex min-w-0 flex-col gap-[3px]">
            <a href={run.url} target="_blank" rel="noopener noreferrer nofollow" className="truncate text-[17px] font-semibold">
              {displayUrl(run.url)}
            </a>
            <span className="text-[14px] text-ink3 [overflow-wrap:anywhere]">Goal · {run.goal}</span>
            {run.start_url && (
              <span className="text-[13px] text-ink3 [overflow-wrap:anywhere]">
                Start link ·{" "}
                <a href={run.start_url} target="_blank" rel="noopener noreferrer nofollow" className="fu-link">
                  {displayUrl(run.start_url)}
                </a>
              </span>
            )}
          </div>
        </div>
        {meta.length > 0 && (
          <ul className="m-0 flex list-none flex-wrap gap-1.5 p-0" aria-label="About this run">
            {meta.map((item) => (
              <li key={item} className="flex h-[30px] items-center whitespace-nowrap rounded-pill border border-line bg-s1 px-[11px] font-code text-[12px] font-medium text-ink2">
                {item}
              </li>
            ))}
          </ul>
        )}
      </div>
      {sections.length > 0 && (
        <nav aria-label="Report sections" className="flex gap-1.5 overflow-x-auto pb-0.5 [scrollbar-width:none]">
          {sections.map(([label, anchor], index) => (
            <a
              key={anchor}
              href={`#${anchor}`}
              className="flex h-9 flex-none items-center gap-2 whitespace-nowrap rounded-pill border-[1.5px] border-ink bg-bg px-3.5 text-[14px] font-medium transition-[background,transform] duration-200 hover:-translate-y-0.5 hover:bg-acc-soft hover:text-ink"
            >
              <span className="font-code text-[11px] font-medium text-ink3">0{index + 1}</span>
              {label}
            </a>
          ))}
        </nav>
      )}
    </div>
  );
}

function InProgress({ run, steps, flags, original }: { run: Run; steps: Step[]; flags: ReportFlags; original?: RunLink | null }) {
  return (
    <>
      {flags.checkAgain && run.retest_of && <RetestView run={run} original={original} />}
      <LiveRun run={run} steps={steps} />
      <FirstImpressionBlock run={run} flags={flags} open />
      {steps.length > 0 && <StepsStrip steps={steps} highlight={new Set()} live />}
    </>
  );
}

function Report({ run, steps, frictions, flags, original }: {
  run: Run;
  steps: Step[];
  frictions: RunDetails["frictions"];
  flags: ReportFlags;
  original?: RunLink | null;
}) {
  const loginHelp = showLoginWallHelp(run, steps);
  const kind = verdictKindOf(run, loginHelp, flags.verdict);
  const title = heroTitle(run, steps, kind, flags);
  const done = run.status === "done";
  // Steps a finding or the verdict points at get a red edge in the strip.
  const highlight = new Set<number>();
  for (const finding of run.findings ?? []) {
    highlight.add(finding.evidence.step);
    for (const seen of finding.also_seen_at ?? []) highlight.add(seen.step);
  }
  if (kind === "stuck" && run.verdict?.where_step != null) highlight.add(run.verdict.where_step);

  return (
    <>
      {flags.checkAgain && run.retest_of && <RetestView run={run} original={original} />}
      <VerdictHero run={run} steps={steps} kind={kind} flags={flags} loginHelp={loginHelp && kind !== "login_wall"} />
      {flags.answers && done && <ShortAnswer run={run} kind={kind} title={title} showBasis={flags.labels} />}
      <FirstImpressionBlock run={run} flags={flags} open={!flags.answers} />
      {done && <Findings run={run} flags={flags} kind={kind} />}
      {frictions.length > 0 && <Frictions frictions={frictions} findings={run.findings} />}
      {flags.checkAgain && done && <CheckAgain run={run} />}
      <StepsStrip steps={steps} highlight={highlight} />
      <HowMade run={run} steps={steps} showFacts={flags.facts} />
      {done && <SharePanel url={run.url} kind={kind} />}
    </>
  );
}

// The first impression, with the hidden-text notice as its own line just above it.
function FirstImpressionBlock({ run, flags, open }: { run: Run; flags: ReportFlags; open: boolean }) {
  const notice = hiddenTextNotice(run.hidden_text, run.first_impression);
  if (!notice && !run.first_impression) return null;
  return (
    <div className="flex flex-col gap-3">
      <HiddenTextLine run={run} />
      {run.first_impression && <FirstImpressionPanel review={run.first_impression} flags={flags} open={open} />}
    </div>
  );
}

function ConnectionNotice() {
  return (
    <p role="status" className="fu-notice m-0">
      Having trouble reaching the server. Still trying…
    </p>
  );
}

function NotFound() {
  return (
    <main className="fu-page gap-5">
      <span className="fu-eyebrow">Report</span>
      <h1 className="fu-display text-pagetitle">We couldn&apos;t find that run</h1>
      <p className="m-0 max-w-[40em] text-[17px] leading-normal text-ink2">
        The link may be mistyped or incomplete. Check it, or start a new run.
      </p>
      <Link href="/#fu-form" className="fu-btn fu-btn-md self-start">
        Start a new run →
      </Link>
    </main>
  );
}
// Shapes returned by GET /api/runs/[id]. Shared by the API route and the run page.

import type { HiddenText } from "./hidden-text.ts";

export type RunStatus = "queued" | "running" | "done" | "failed";
export type Outcome =
  | "achieved"
  | "achieved_unconfirmed"
  | "not_achieved"
  | "unverified"
  | "gave_up"
  | "blocked"
  | "max_steps"
  | "error";

export type Clarity = "yes" | "partly" | "no";

// How the founder chose to let the visitor in (the form's "How should the visitor get in?").
export type AccessMode = "public" | "link" | "account" | "signup";

// What a newcomer sees on the landing page without logging in (written by the worker).
export type FirstImpression = {
  what_it_does: { clear: Clarity; summary: string };
  who_its_for: { clear: Clarity; summary: string };
  main_action: { obvious: Clarity; summary: string };
  hesitations: string[];
  suggestions: string[];
};

// What happened after the visitor submitted a login or sign-up form (worker/login_diagnosis.py).
export type LoginDiagnosis = {
  stage: "sign_in" | "sign_up";
  result: "signed_in" | "rejected" | "needs_verification" | "no_effect";
  challenge: "email_verification" | "captcha" | "two_factor" | null;
  page_message: string | null;
  http_statuses: string[];
  step: number | null;
  url: string | null;
  detail?: string;
};

// Which way in the visit used. Never holds a credential: the test login's values are not stored here.
export type Entry = {
  start_link: string | null;
  access_mode?: AccessMode;
  // A login written on the page itself (a demo login for visitors), typed with the page's own values.
  page_login?: "not_used" | "shown_on_page" | "typed";
  // That login was accepted: the password field went away and the visit moved on. Absent on older runs.
  page_login_worked?: boolean;
  diagnosis?: LoginDiagnosis | null;
  // The site showed a bot check ("Verify you are human"); the visit did not try to get past it.
  bot_check?: { phrase: string; url: string; title: string; step: number } | null;
  test_login: "not_provided" | "provided_not_used" | "used" | "failed";
  self_signup: "not_used" | "used" | "blocked_verification" | "blocked_third_party" | "failed";
  third_party_options: string[];
  created_account_email: string | null;
  blocked_at_login: boolean;
};

// One ranked problem from the report writer (worker/report_writer.py). Every one points at a real step.
export type Finding = {
  title: string;
  severity: "high" | "medium" | "low";
  kind: "site_problem" | "unclear_wording" | "hidden_error";
  expected: string;
  happened: string;
  evidence: {
    step: number;
    url: string | null;
    screenshot_url: string | null;
    page_errors: string[];
    quote: string | null;
  };
  reproduce: string[];
  fix_prompt: string;
  // Steps of the problems the visitor noted that this finding covers, so they are not listed twice.
  covers_steps?: number[];
  // The problem is observed in the run; the fix is our recommendation. Absent on older findings.
  basis?: "observed";
  fix_basis?: "recommendation";
  // Three to five checks a person can make by looking at the page after the change.
  acceptance_criteria?: string[];
  // The same symptom seen again, merged into this finding: the earliest step is `evidence`, these are the rest.
  also_seen_at?: { step: number; url: string | null; screenshot_url: string | null; page_errors: string[] }[];
};

// What a statement in the report rests on: the run record, the independent check, or our suggestion.
export type Basis = "observed" | "verified" | "recommendation";

export type VerdictKind = "got_through" | "unconfirmed" | "stuck" | "login_wall" | "bot_check" | "our_failure";

// One verdict per run (worker/verdict.py).
export type Verdict = {
  kind: VerdictKind;
  headline: string;
  where_step: number | null;
  where_url: string | null;
  evidence_quote: string;
  basis: "observed" | "verified";
  detail?: string;
  ways_in?: string[];
};

// How the report was made (worker/run_facts.py): counted from the run, not written by a model.
export type RunFacts = {
  steps_taken: number;
  recoveries: { step: number; rung: string; how: string; instruction: string }[];
  own_issues: { step: number | null; instruction: string; reason: string | null }[];
  page_reloads: number;
  page_errors: string[];
  page_error_count: number;
  verifier: { verdict: string | null; quote: string } | null;
  success_condition: string | null;
  checked_without_success_condition: boolean;
  cost_usd: number;
  duration_seconds: number;
  agent_version?: string;
  worker_id?: string;
  trace_id?: string | null;
};

// Check again (worker/retest.py): what happened to each finding of the original run.
export type RetestLabel = "fixed" | "still_present" | "not_reached" | "inconclusive" | "new";

export type RetestItem = {
  finding_index?: number;
  title: string;
  kind?: string;
  severity?: string;
  original_step?: number | null;
  original_url?: string | null;
  label: RetestLabel;
  // Which pass produced the label: the independent visit, or the guided follow-up along the original route.
  pass?: "independent" | "guided" | null;
  // A step of this (the retest's) report.
  evidence_step: number | null;
  reason?: string;
  basis?: "observed";
};

export type RetestVerdictSide = {
  kind: VerdictKind;
  headline: string;
  where_step: number | null;
  where_url: string | null;
} | null;

export type RetestResult = {
  original_run_id?: string;
  labels: RetestItem[];
  new: RetestItem[];
  counts?: Record<string, number>;
  verdict?: { before: RetestVerdictSide; after: RetestVerdictSide; change: string; summary: string };
  fixed_means?: string;
  guided?: { attempted: number; followed: number };
  error?: string;
};

export type Run = {
  id: string;
  url: string;
  start_url: string | null;
  has_test_login: boolean;
  access_mode: AccessMode | null;
  first_impression: FirstImpression | null;
  // Evidence that the page hid instructions aimed at AI agents (worker/hidden_text.py): where and how, never the
  // text. Read from the run's result only for this field. See lib/hidden-text.ts for what the page shows of it.
  hidden_text?: HiddenText;
  entry: Entry | null;
  findings: Finding[] | null;
  verdict: Verdict | null;
  run_facts: RunFacts | null;
  success_condition: string | null;
  retest_of: string | null;
  retest: RetestResult | null;
  goal: string;
  status: RunStatus;
  outcome: Outcome | null;
  reason: string | null;
  cost_usd: number | string | null;
  brain_model: string | null;
  created_at: string;
  started_at: string | null;
  finished_at: string | null;
};

export type Step = {
  idx: number;
  tool: string;
  thought: string | null;
  input: Record<string, unknown> | null;
  result: Record<string, unknown> | null;
  url: string | null;
  screenshot_path: string | null;
  created_at: string;
};

export type Friction = {
  id: number;
  step_idx: number | null;
  kind: "site" | "agent_issue";
  severity: "low" | "medium" | "high" | null;
  expected: string | null;
  happened: string | null;
};

// The original of a retest, and the latest check of a run (either may be absent).
export type RunLink = { id: string; status?: string; verdict?: Verdict | null; outcome?: Outcome | null };

export type RunDetails = {
  run: Run;
  steps: Step[];
  frictions: Friction[];
  original?: RunLink | null;
  latest_retest?: RunLink | null;
};

export type ApiError = { error: string; message: string };

// Never includes the test login: it lives in run_secrets, which the web app never reads. Of the run's raw
// result, only the hidden-text evidence is read.
// One string literal, so supabase-js can infer the row type from it.
export const RUN_COLUMNS =
  "id, url, start_url, has_test_login, access_mode, first_impression, hidden_text:result->hidden_text, entry, findings, verdict, run_facts, success_condition, retest_of, retest, goal, status, outcome, reason, cost_usd, brain_model, created_at, started_at, finished_at";
// The same without the columns added on 2026-10-11 (access_mode, findings), for a database whose schema
// has not been updated yet: the run page still loads, without them.
export const RUN_COLUMNS_BEFORE_FINDINGS = RUN_COLUMNS.replace(" access_mode,", "")
  .replace(" findings,", "")
  .replace(" verdict,", "")
  .replace(" run_facts,", "")
  .replace(" success_condition,", "")
  .replace(" retest_of,", "")
  .replace(" retest,", "");
export const STEP_COLUMNS = "idx, tool, thought, input, result, url, screenshot_path, created_at";
export const FRICTION_COLUMNS = "id, step_idx, kind, severity, expected, happened";
// Shapes of a product brief (worker/understand.py writes it; /api/briefs/[id] returns it).

export type ClaimStatus = "confirmed" | "inferred" | "unknown";
export type PricingStatus = "published" | "not_published" | "unclear";

export type BriefClaim = {
  claim: string;
  source_url: string;
  status: ClaimStatus;
  // A short exact quote from the source page; empty unless the claim is confirmed.
  quote: string;
};

export type PricingTier = { name: string; price: string; what_you_get: string; source_url: string };

export type SuggestedJourney = {
  goal: string;
  // How we would know it worked.
  success: string;
  source_url: string;
  basis: "call_to_action" | "claim";
  basis_text: string;
  // A site's claim is a goal to test, never proof that it works.
  claim_to_test: boolean;
};

// Written by the worker's code, not by a model: shown when a page held text hidden from people and addressed to
// automated agents. The brief records where it was found, never the text.
export const HIDDEN_TEXT_NOTICE =
  "This page contains hidden text addressed to automated agents. It is not visible to people and was ignored.";

export type HiddenTextNote = {
  notice: string;
  found: { url: string; where: string; method: string; blocks: number }[];
};

export type Brief = {
  version: number;
  url: string;
  one_liner: string;
  what_it_does: string;
  who_its_for: string;
  how_it_works: string;
  primary_value: string;
  pricing: { status: PricingStatus; tiers: PricingTier[]; note: string; source_urls: string[] };
  business_model: { label: "inferred"; model: string; evidence: { quote: string; source_url: string }[] };
  claims: BriefClaim[];
  unknowns: string[];
  suggested_journeys: SuggestedJourney[];
  pages: { url: string; kind: string; title: string; method: "http" | "browser"; status: number; bytes: number }[];
  skipped: { url: string; kind: string; reason: string }[];
  limits: { seconds: number; browser_reads: number; stopped: string | null };
  hidden_text?: HiddenTextNote | null;
};

// A site that could not be read: the run is "failed" and the brief says why, in words for the visitor.
export type BriefFailure = { status: "could_not_read"; message: string };

export type BriefRun = {
  id: string;
  url: string;
  status: "queued" | "running" | "done" | "failed";
  brief: Brief | BriefFailure | null;
  cost_usd: number | string | null;
  created_at: string;
  started_at: string | null;
  finished_at: string | null;
};

// One string literal, so supabase-js can infer the row type from it.
export const BRIEF_COLUMNS = "id, url, status, brief, cost_usd, created_at, started_at, finished_at";
import "server-only";

import { supabase } from "@/lib/supabase";

// A test run started from a brief records which brief it came from (runs.brief_run_id). Both steps are
// best-effort: a database that has not had the "Understand mode" SQL yet still starts the test.

export async function briefExists(briefId: string): Promise<boolean> {
  const { data, error } = await supabase()
    .from("runs")
    .select("id")
    .eq("id", briefId)
    .eq("kind", "understand")
    .maybeSingle();
  if (error) {
    console.error("Looking up the brief failed:", error.message);
    return false;
  }
  return !!data;
}

export async function recordBrief(runId: string, briefId: string): Promise<void> {
  const { error } = await supabase().from("runs").update({ brief_run_id: briefId }).eq("id", runId);
  if (error) console.error("Recording the brief on the run failed:", error.message);
}
// What a run was started with (address and goal), remembered in this browser tab for the moment between
// starting it and its first response, so the waiting page can show them at once. Presentation only: nothing is
// sent anywhere, and storage that is missing or throws just means the page waits for the server.

export type PendingRun = { url: string; goal: string };

function key(id: string): string {
  return `fu-run:${id}`;
}

export function rememberPendingRun(id: string, run: PendingRun): void {
  try {
    sessionStorage.setItem(key(id), JSON.stringify({ url: run.url, goal: run.goal }));
  } catch {
    // The waiting page shows the address once the server answers.
  }
}

// The raw stored string (a stable snapshot for useSyncExternalStore), or null.
export function pendingRunSnapshot(id: string): string | null {
  try {
    return sessionStorage.getItem(key(id));
  } catch {
    return null;
  }
}

export function parsePendingRun(raw: string | null): PendingRun | null {
  if (!raw) return null;
  try {
    const value = JSON.parse(raw) as Partial<PendingRun>;
    return typeof value.url === "string" && typeof value.goal === "string" ? { url: value.url, goal: value.goal } : null;
  } catch {
    return null;
  }
}

content.content:
"use client";

import Link from "next/link";
import { useEffect, useState } from "react";

import { hiddenTextNote, isBrief, isFailure, safeHref, sortClaims, testJourneyHref } from "@/lib/brief-logic";
import type { Brief, BriefClaim, BriefRun, ClaimStatus, SuggestedJourney } from "@/lib/brief-types";
import { grid } from "@/lib/css";
import { founderBriefEnabled } from "@/lib/founder-flag";
import { siteName } from "@/lib/report-view";

import { FounderView } from "./founder-view";
import { HiddenTextNotice } from "./hidden-text-notice";
import { SourceLink } from "./source-link";

const POLL_MS = 2000;

type State = { kind: "loading" } | { kind: "not_found" } | { kind: "ready"; run: BriefRun };

export function BriefView({ id }: { id: string }) {
  const [state, setState] = useState<State>({ kind: "loading" });
  const [connectionTrouble, setConnectionTrouble] = useState(false);

  useEffect(() => {
    let cancelled = false;
    let timer: ReturnType<typeof setTimeout> | undefined;

    async function poll() {
      try {
        const response = await fetch(`/api/briefs/${encodeURIComponent(id)}`, { cache: "no-store" });
        if (cancelled) return;
        if (response.status === 404) {
          setState({ kind: "not_found" });
          return;
        }
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const { run } = (await response.json()) as { run: BriefRun };
        if (cancelled) return;
        setState({ kind: "ready", run });
        setConnectionTrouble(false);
        if (run.status === "done" || run.status === "failed") return;
      } catch {
        if (cancelled) return;
        setConnectionTrouble(true);
      }
      timer = setTimeout(poll, POLL_MS);
    }

    poll();
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [id]);

  if (state.kind === "loading") {
    return (
      <main className="fu-page gap-4">
        <p role="status" className="m-0 font-code text-[13px] text-ink3">
          Loading the brief…
        </p>
        {connectionTrouble && <ConnectionNotice />}
      </main>
    );
  }
  if (state.kind === "not_found") {
    return (
      <main className="fu-page gap-5">
        <span className="fu-eyebrow">Understand</span>
        <h1 className="fu-display text-pagetitle">We couldn&apos;t find that brief</h1>
        <p className="m-0 text-[17px] text-ink2">The link may be mistyped, or the brief may no longer exist.</p>
        <Link href="/?mode=understand#fu-form" className="fu-btn fu-btn-md self-start">
          Understand a website →
        </Link>
      </main>
    );
  }

  const { run } = state;
  const ready = isBrief(run.brief) && run.status === "done";
  return (
    <main className="fu-page" style={{ gap: "clamp(36px,5cqi,56px)" }}>
      {ready ? (
        <Ready id={run.id} run={run} brief={run.brief as Brief} />
      ) : (
        <>
          <BriefHeader run={run} />
          {connectionTrouble && <ConnectionNotice />}
          {run.status === "queued" || run.status === "running" ? (
            <InProgress queued={run.status === "queued"} />
          ) : (
            <Failed message={isFailure(run.brief) ? run.brief.message : null} />
          )}
        </>
      )}
    </main>
  );
}

function BriefHeader({ run, tabs }: { run: BriefRun; tabs?: React.ReactNode }) {
  return (
    <div className="flex flex-wrap items-end justify-between gap-[18px]">
      <div className="flex min-w-0 flex-col gap-2.5">
        <span className="fu-eyebrow">
          Understand ·{" "}
          <a href={safeHref(run.url) ?? undefined} target="_blank" rel="noopener noreferrer nofollow" className="fu-link">
            {siteName(run.url)}
          </a>
        </span>
        <h1 className="fu-display text-pagetitle" style={{ overflowWrap: "anywhere" }}>
          {siteName(run.url)}
        </h1>
      </div>
      {tabs}
    </div>
  );
}

function ConnectionNotice() {
  return (
    <p role="status" className="fu-notice m-0">
      We lost the connection for a moment. Still trying.
    </p>
  );
}

function InProgress({ queued }: { queued: boolean }) {
  return (
    <section role="status" className="fu-card-sm flex flex-col gap-3 p-6">
      <span className="flex items-center gap-2 font-code text-[12px] font-medium uppercase tracking-[.06em] text-ink3">
        <span aria-hidden className="size-2 rounded-full" style={{ background: queued ? "var(--ink4)" : "var(--pass)", animation: "fuBlink 1.6s ease-in-out infinite" }} />
        {queued ? "Waiting for a free worker" : "Reading the site now"}
      </span>
      <p className="m-0 text-[16px] leading-normal text-ink2">
        We read the homepage and a few more public pages, then write the brief. This usually takes under a minute. This page
        updates by itself, and you can come back to this link later.
      </p>
    </section>
  );
}

function Failed({ message }: { message: string | null }) {
  return (
    <section role="alert" className="flex flex-col gap-3 rounded-cardsm border-[1.5px] border-dashed border-ink p-6">
      <h2 className="m-0 text-[19px] font-semibold">We couldn&apos;t write a brief for this site</h2>
      <p className="m-0 text-[16px] leading-normal text-ink2">{message ?? "Something went wrong on our side. Please try again in a minute."}</p>
      <Link href="/?mode=understand#fu-form" className="fu-btn fu-btn-md self-start">
        Try another website →
      </Link>
    </section>
  );
}

function Ready({ id, run, brief }: { id: string; run: BriefRun; brief: Brief }) {
  const [tab, setTab] = useState<"product" | "founder">("product");
  // The founder brief is behind NEXT_PUBLIC_FOUNDER_BRIEF; without it this page is the product brief alone.
  const founder = founderBriefEnabled();
  const tabs = founder ? (
    <div role="tablist" aria-label="Which brief" className="flex gap-1 rounded-pill border-[1.5px] border-ink bg-s1 p-1">
      {(
        [
          ["product", "Product brief"],
          ["founder", "Founder brief"],
        ] as const
      ).map(([value, label]) => {
        const on = tab === value;
        return (
          <button
            key={value}
            type="button"
            role="tab"
            aria-selected={on}
            onClick={() => setTab(value)}
            className="h-10 cursor-pointer whitespace-nowrap rounded-pill border-none px-4 text-[14px] font-semibold"
            style={{ background: on ? "var(--ink)" : "transparent", color: on ? "var(--bg)" : "var(--ink)" }}
          >
            {label}
          </button>
        );
      })}
    </div>
  ) : null;
  return (
    <>
      <BriefHeader run={run} tabs={tabs} />
      {founder && tab === "founder" ? <FounderView briefId={id} /> : <ProductBrief id={id} brief={brief} />}
    </>
  );
}

function ProductBrief({ id, brief }: { id: string; brief: Brief }) {
  const hidden = hiddenTextNote(brief);
  const overview: [string, string][] = [
    ["What it does", brief.what_it_does],
