const STATUS: Record<ClaimStatus, { label: string; bg: string; fg: string }> = {
  confirmed: { label: "Confirmed", bg: "var(--green-soft)", fg: "var(--green-ink)" },
  inferred: { label: "Inferred", bg: "var(--amber-soft)", fg: "var(--amber-ink)" },
