    if (window.location.hash === `#${FORM_ANCHOR}`) focus();
    return () => window.removeEventListener(START_TEST_EVENT, focus);
  }, []);

  const testing = tab === "test";
  const accessLabel = (ACCESS.find((option) => option.id === access) ?? ACCESS[0]).t.toLowerCase();
  const next = testing
    ? [
